1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = {
11	  id: number;
12	  name: string;
13	  clientId: number;
14	  clientName: string;
15	  archived: boolean;
16	};
17	type Invoice = {
18	  id: number;
19	  projectId: number;
20	  amount: number;
21	  status: string;
22	  issuedDate: string;
23	  dueDate: string;
24	};
25	type Task = { id: number; projectId: number; title: string; done: boolean };
26	type Tag = { id: number; name: string };
27	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
28	
29	type LineItem = {
30	  id: number;
31	  invoiceId: number;
32	  description: string;
33	  qty: number;
34	  unitPrice: number;
35	};
36	
37	function money(amount: number): string {
38	  return `$${Number(amount).toFixed(2)}`;
39	}
40	
41	// One charge line while it is being edited on screen: the fields are held as raw strings so the
42	// inputs stay controlled and the total can recompute live as they change.
43	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
44	
45	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
46	// many, price each), the total worked out for you, and a form to add another line. Each line can be
47	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
48	// own line-item state, scoped to the one invoice it is showing.
49	function InvoiceDetail({
50	  invoiceId,
51	  onChange,
52	  onClose,
53	}: {
54	  invoiceId: number;
55	  onChange: () => void;
56	  onClose: () => void;
57	}) {
58	  const [items, setItems] = useState<EditItem[]>([]);
59	  const [description, setDescription] = useState('');
60	  const [qty, setQty] = useState('');
61	  const [unitPrice, setUnitPrice] = useState('');
62	
63	  async function load() {
64	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
65	    const rows: LineItem[] = await res.json();
66	    setItems(
67	      rows.map((li) => ({
68	        id: li.id,
69	        description: li.description,
70	        qty: String(li.qty),
71	        unitPrice: String(li.unitPrice),
72	      })),
73	    );
74	  }
75	
76	  useEffect(() => {
77	    void load();
78	  }, [invoiceId]);
79	
80	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
81	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
82	  }
83	
84	  function amountOf(li: EditItem): number {
85	    const line = Number(li.qty) * Number(li.unitPrice);
86	    return Number.isFinite(line) ? line : 0;
87	  }
88	
89	  async function save(li: EditItem) {
90	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
91	      return;
92	    }
93	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
94	      method: 'POST',
95	      headers: { 'Content-Type': 'application/json' },
96	      body: JSON.stringify({
97	        description: li.description,
98	        qty: Number(li.qty),
99	        unitPrice: Number(li.unitPrice),
100	      }),
101	    });
102	    await load();
103	    onChange();
104	  }
105	
106	  async function remove(id: number) {
107	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
108	    await load();
109	    onChange();
110	  }
111	
112	  async function submit(e: React.FormEvent) {
113	    e.preventDefault();
114	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
115	      return;
116	    }
117	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
118	      method: 'POST',
119	      headers: { 'Content-Type': 'application/json' },
120	      body: JSON.stringify({
121	        description,
122	        qty: Number(qty),
123	        unitPrice: Number(unitPrice),
124	      }),
125	    });
126	    setDescription('');
127	    setQty('');
128	    setUnitPrice('');
129	    await load();
130	    onChange();
131	  }
132	
133	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
134	
135	  return (
136	    <section data-testid="invoice-detail">
137	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
138	        Back to invoices
139	      </button>
140	
141	      <table data-testid="invoice-lineitems-table">
142	        <tbody>
143	          {items.map((li) => (
144	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
145	              <td>
146	                <input
147	                  data-testid="lineitem-description"
148	                  value={li.description}
149	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
150	                />
151	              </td>
152	              <td>
153	                <input
154	                  data-testid="lineitem-qty"
155	                  value={li.qty}
156	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
157	                />
158	              </td>
159	              <td>
160	                <input
161	                  data-testid="lineitem-unitprice"
162	                  value={li.unitPrice}
163	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
164	                />
165	              </td>
166	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
167	              <td>
168	                <button
169	                  data-testid={`lineitem-save-${li.id}`}
170	                  type="button"
171	                  onClick={() => save(li)}
172	                >
173	                  Save
174	                </button>
175	                <button
176	                  data-testid={`lineitem-remove-${li.id}`}
177	                  type="button"
178	                  onClick={() => remove(li.id)}
179	                >
180	                  Remove
181	                </button>
182	              </td>
183	            </tr>
184	          ))}
185	        </tbody>
186	      </table>
187	
188	      <p data-testid="invoice-amount">{money(total)}</p>
189	
190	      <form data-testid="lineitem-form" onSubmit={submit}>
191	        <input
192	          data-testid="lineitem-form-description"
193	          placeholder="Description"
194	          value={description}
195	          onChange={(e) => setDescription(e.target.value)}
196	        />
197	        <input
198	          data-testid="lineitem-form-qty"
199	          placeholder="How many"
200	          value={qty}
201	          onChange={(e) => setQty(e.target.value)}
202	        />
203	        <input
204	          data-testid="lineitem-form-unitprice"
205	          placeholder="Price each"
206	          value={unitPrice}
207	          onChange={(e) => setUnitPrice(e.target.value)}
208	        />
209	        <button data-testid="lineitem-form-submit" type="submit">
210	          Add line item
211	        </button>
212	      </form>
213	    </section>
214	  );
215	}
216	
217	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
218	// own invoice state, scoped to the one project it is showing.
219	function ProjectDetail({ project }: { project: Project }) {
220	  const [invoices, setInvoices] = useState<Invoice[]>([]);
221	  const [tasks, setTasks] = useState<Task[]>([]);
222	  const [tags, setTags] = useState<Tag[]>([]);
223	  const [allTags, setAllTags] = useState<Tag[]>([]);
224	  const [tagToAdd, setTagToAdd] = useState('');
225	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
226	  const [amount, setAmount] = useState('');
227	  const [amountError, setAmountError] = useState('');
228	  const [sortByDue, setSortByDue] = useState(false);
229	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
230	  const [notes, setNotes] = useState<Note[]>([]);
231	  const [noteText, setNoteText] = useState('');
232	
233	  async function load() {
234	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
235	    setInvoices(await res.json());
236	  }
237	
238	  async function loadNotes() {
239	    const res = await fetch(`/api/notes?targetType=project&targetId=${project.id}`);
240	    setNotes(await res.json());
241	  }
242	
243	  async function submitNote(e: React.FormEvent) {
244	    e.preventDefault();
245	    if (!noteText.trim()) {
246	      return;
247	    }
248	    await fetch('/api/notes', {
249	      method: 'POST',
250	      headers: { 'Content-Type': 'application/json' },
251	      body: JSON.stringify({ targetType: 'project', targetId: project.id, text: noteText }),
252	    });
253	    setNoteText('');
254	    await loadNotes();
255	  }
256	
257	  async function loadTasks() {
258	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
259	    setTasks(await res.json());
260	  }
261	
262	  async function loadTags() {
263	    const [mine, all] = await Promise.all([
264	      fetch(`/api/projects/${project.id}/tags`).then((r) => r.json()),
265	      fetch('/api/tags').then((r) => r.json()),
266	    ]);
267	    setTags(mine);
268	    setAllTags(all);
269	  }
270	
271	  useEffect(() => {
272	    void load();
273	    void loadTasks();
274	    void loadTags();
275	    void loadNotes();
276	  }, [project.id]);
277	
278	  async function toggleTask(id: number) {
279	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
280	    await loadTasks();
281	  }
282	
283	  async function addTag(e: React.FormEvent) {
284	    e.preventDefault();
285	    if (!tagToAdd) {
286	      return;
287	    }
288	    await fetch(`/api/projects/${project.id}/tags`, {
289	      method: 'POST',
290	      headers: { 'Content-Type': 'application/json' },
291	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
292	    });
293	    setTagToAdd('');
294	    await loadTags();
295	  }
296	
297	  async function removeTag(id: number) {
298	    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
299	    await loadTags();
300	  }
301	
302	  async function submit(e: React.FormEvent) {
303	    e.preventDefault();
304	    const value = Number(amount);
305	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
306	      setAmountError('Amount must be more than zero');
307	      return;
308	    }
309	    setAmountError('');
310	    await fetch('/api/invoices', {
311	      method: 'POST',
