313	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
314	    });
315	    setAmount('');
316	    await load();
317	  }
318	
319	  async function send(id: number) {
320	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
321	    await load();
322	  }
323	
324	  async function pay(id: number) {
325	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
326	    await load();
327	  }
328	
329	  const shownTasks = tasks.filter((t) =>
330	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
331	  );
332	
333	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
334	  const shownInvoices = sortByDue
335	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
336	    : invoices;
337	
338	  return (
339	    <section data-testid="project-detail">
340	      <h2 data-testid="project-detail-name">{project.name}</h2>
341	
342	      <div data-testid="project-tags">
343	        {tags.map((tag) => (
344	          <span key={tag.id}>
345	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
346	            <button
347	              data-testid={`project-tag-remove-${tag.id}`}
