354	        ))}
355	      </div>
356	
357	      <form data-testid="project-tag-form" onSubmit={addTag}>
358	        <select
359	          data-testid="project-tag-add"
360	          value={tagToAdd}
361	          onChange={(e) => setTagToAdd(e.target.value)}
362	        >
363	          <option value="">Add a label</option>
364	          {allTags
365	            .filter((t) => !tags.some((mine) => mine.id === t.id))
366	            .map((t) => (
367	              <option key={t.id} value={String(t.id)}>
368	                {t.name}
