379	        value={taskFilter}
380	        onChange={(e) => setTaskFilter(e.target.value as 'ALL' | 'OPEN' | 'DONE')}
381	      >
382	        <option value="ALL">All tasks</option>
383	        <option value="OPEN">Open</option>
384	        <option value="DONE">Done</option>
385	      </select>
386	
387	      <table data-testid="project-tasks-table">
388	        <tbody>
